class Solution {
public:
    int minUnlockedIndices(vector<int>& nums, vector<int>& locked) {
        int n = nums.size();
        bool seen3 = false;
        for (int x : nums) { if (x == 3) seen3 = true; else if (x == 1 && seen3) return -1; }
        vector<int> suf1(n + 1, 0), suf2(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) { suf1[i] = suf1[i + 1] + (nums[i] == 1); suf2[i] = suf2[i + 1] + (nums[i] == 2); }
        int pre2 = 0, pre3 = 0, ans = 0;
        for (int i = 0; i < n - 1; i++) {
            pre2 += nums[i] == 2; pre3 += nums[i] == 3;
            bool need = (pre2 > 0 && suf1[i + 1] > 0) || (pre3 > 0 && suf2[i + 1] > 0);
            if (need && locked[i]) ans++;
        }
        return ans;
    }
};

