class Solution {
    public int minUnlockedIndices(int[] nums, int[] locked) {
        int n = nums.length;
        boolean seen3 = false;
        for (int x : nums) { if (x == 3) seen3 = true; else if (x == 1 && seen3) return -1; }
        int[] suf1 = new int[n + 1], suf2 = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) { suf1[i] = suf1[i + 1] + (nums[i] == 1 ? 1 : 0); suf2[i] = suf2[i + 1] + (nums[i] == 2 ? 1 : 0); }
        int pre2 = 0, pre3 = 0, ans = 0;
        for (int i = 0; i < n - 1; i++) {
            pre2 += nums[i] == 2 ? 1 : 0; pre3 += nums[i] == 3 ? 1 : 0;
            boolean need = (pre2 > 0 && suf1[i + 1] > 0) || (pre3 > 0 && suf2[i + 1] > 0);
            if (need && locked[i] == 1) ans++;
        }
        return ans;
    }
}

