    let pre2 = 0, pre3 = 0, ans = 0;
    for (let i = 0; i < n - 1; i++) {
        pre2 += nums[i] === 2; pre3 += nums[i] === 3;
        const need = (pre2 > 0 && suf1[i + 1] > 0) || (pre3 > 0 && suf2[i + 1] > 0);
